-- Select your application database in phpMyAdmin before importing this migration.
CREATE TABLE IF NOT EXISTS spot_campaigns (spot_id VARCHAR(64) PRIMARY KEY,spot_name VARCHAR(255) NOT NULL,category_id BIGINT UNSIGNED NULL,target_scope ENUM('ALL_PUBLIC','WHITELIST','NEW_USER') NOT NULL DEFAULT 'ALL_PUBLIC',whitelisted_users JSON NULL,city_zone VARCHAR(128) NULL,venue_name VARCHAR(255) NULL,latitude DECIMAL(10,7) NOT NULL,longitude DECIMAL(10,7) NOT NULL,proximity_alert_radius INT UNSIGNED NOT NULL DEFAULT 30,scanner_unlock_radius INT UNSIGNED NOT NULL DEFAULT 20,indoor_micro_clue TEXT NULL,reward_type ENUM('PROMO_CASH','COUPON_VOUCHER','DIRECT_CASH','MILESTONE') NOT NULL DEFAULT 'PROMO_CASH',reward_amount DECIMAL(18,2) NOT NULL DEFAULT 15,min_cart_value DECIMAL(18,2) NOT NULL DEFAULT 300,ttl_minutes INT UNSIGNED NOT NULL DEFAULT 30,auto_reversal TINYINT(1) NOT NULL DEFAULT 1,max_budget_scans INT UNSIGNED NOT NULL DEFAULT 500,scan_frequency_policy ENUM('PER_DEVICE','SINGLE_USE','DAILY','POOL') NOT NULL DEFAULT 'PER_DEVICE',is_active TINYINT(1) NOT NULL DEFAULT 1,created_by INT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES video_categories(id),FOREIGN KEY(created_by) REFERENCES admins(id),INDEX idx_spot_active(is_active,category_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS riddle_pool (riddle_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,spot_id VARCHAR(64) NOT NULL,riddle_text TEXT NOT NULL,primary_answer VARCHAR(128) NOT NULL,synonyms JSON NOT NULL,yt_video_id VARCHAR(32) NULL,weight_percentage INT UNSIGNED NOT NULL DEFAULT 100,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(spot_id) REFERENCES spot_campaigns(spot_id) ON DELETE CASCADE,INDEX idx_riddle_spot(spot_id,weight_percentage)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS scan_audit_ledger (audit_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,device_hash VARCHAR(128) NOT NULL,user_id BIGINT UNSIGNED NOT NULL,spot_id VARCHAR(64) NOT NULL,riddle_id BIGINT UNSIGNED NULL,user_input_answer TEXT NULL,is_correct TINYINT(1) NOT NULL DEFAULT 0,attempt_count INT UNSIGNED NOT NULL DEFAULT 1,gps_lat_submitted DECIMAL(10,7) NULL,gps_lng_submitted DECIMAL(10,7) NULL,distance_calculated_m DECIMAL(12,2) NULL,status ENUM('PASS','WRONG_ATTEMPT','BLOCKED_DEVICE','EXHAUSTED','EXPIRED','SETTLED') NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(spot_id) REFERENCES spot_campaigns(spot_id),FOREIGN KEY(riddle_id) REFERENCES riddle_pool(riddle_id),INDEX idx_scan_audit_spot(spot_id,created_at),INDEX idx_scan_device(device_hash,spot_id)) ENGINE=InnoDB;
INSERT IGNORE INTO admin_permissions(code,description) VALUES ('campaigns.manage','Manage master spot campaigns'),('campaigns.audit','View campaign scan audit');
ALTER TABLE spot_campaigns ADD COLUMN master_token_hash CHAR(64) NOT NULL UNIQUE AFTER spot_id;
